func compositionOf(ctx context.Context, spec dsl.Spec, in RunSuiteIn) (composition, error) {
	chain := spec.Chain.Name
	if in.Chain != "" && in.Chain != chain {
		return composition{}, fmt.Errorf("the request names chain %q but the spec declares %q", in.Chain, chain)
	}
	keysDir := in.KeysDir
	keysSource := in.KeysSource
	keysValidators := 0
	if k := spec.EnvKeys; k != nil {
		if keysSource == "" {
			keysSource = k.Source
		}
		if keysDir == "" {
			keysDir = expand(k.Ref)
		}
		keysValidators = k.Validators
	}
	if keysDir == "" {
		// A generated set — or a node table that pins per-node keys — goes to a
		// workspace-local dir, not the shared preset. The key sources reuse
		// whatever set already sits at the dir, so defaulting to presets/keys
		// would silently reuse the preset's identities (and ignore the pinned
		// keys, or fail when the network wants more than the preset holds)
		// instead of building a fresh set. Preset stays the default otherwise.
		if keysSource == keySourceGenerate || topologyHasKeys(spec.Topology) {
			keysDir = filepath.Join(in.DataDir, generatedKeysSubdir)
		} else {
			keysDir = defaultKeysDir
		}
	}
	overlayPath, err := writeOverlay(ctx, in.DataDir, spec.Chain.GenesisOverlay)
	if err != nil {
		return composition{}, err
	}

// Registry holds the action, assertion and reader implementations a run
// dispatches on, injected as an instance rather than a package global. The
// grammar and the interpreter know the names only as strings; what a name
// does is registered from outside (the testhelper module registers the
// built-ins), which is what keeps this package free of chain vocabulary.
type Registry interface {
	Action(name string) (Action, bool)
	Assertion(name string) (Assertion, bool)
	// Reader is a named source the "read" and "waitFor" actions draw from.
	// Registered beside the assertions so the two share one vocabulary — a
	// spec reads "chainId" with the same word it asserts it by.
	Reader(name string) (Reader, bool)
	RegisterAction(name string, a Action)
	RegisterAssertion(name string, a Assertion)
	RegisterReader(name string, r Reader)
}

