// A suite composes the network its specs declare. The declaration is the
// env half of a v2 case (or a v1 spec's chain block); this file turns it into
// the request a composer takes. There are two composers — the workspace
// steps for a single-binary network, and the handoff for a mixed-binary one —
// and the declaration's shape picks between them. Nothing here asks which
// chain it is.

func head(t *testing.T, url string) int64 {
	c := rpc.Dial(url)
	bn, err := c.BlockNumber(context.Background())
	if err != nil {
		return -1
	}
	return int64(bn)
}

// Package networkcmd is the CLI mirror of the MCP named-network registry tools
// (chainbench_network_* and chainbench_remote_rpc). It gives an operator the
// same reach an agent has: attach to an already-running network by URL, list
// and inspect the saved networks, and call a method on one by name — the
// registry was MCP-only before (WA5). Every subcommand is flag decoding plus one
// internal/app call, the same function the MCP tool binds, so the two surfaces
// cannot drift.
package networkcmd

Actions   Registry
	// Nodes controls node processes for fault-injection steps (stopNode /
	// startNode / restartNode). It is nil when the run does not own the node
	// processes — attach mode — and those actions then fail with a clear reason
	// rather than silently doing nothing.
	Nodes NodeControl
}
